class Solution {
    public String reverseString(String s) {
        char[] chars = s.toCharArray();
        for (int l = 0, r = chars.length - 1; l < r; l++, r--) {
            char t = chars[l];
            chars[l] = chars[r];
            chars[r] = t;
        }
        return new String(chars);
    }
}

